output_text:
[
  {
    "id": "must_take_cart",
    "text": "A shopper should obtain a cart before completing the shopping trip.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "cartObtained": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    },
    "justification": "The rule refers only to possession of a cart, not to any particular cart bay or coordinate, so it applies in any store."
  },
  {
    "id": "exit_with_cart",
    "text": "A shopper must not leave the store without the cart they were using.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    },
    "justification": "The rule is defined by the exit action and cart possession rather than by the physical location of the exit."
  },
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "Carts should not be taken into single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "or": [
            {
              "and": [
                "adjShelf",
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "adjShelf",
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    },
    "justification": "The abstraction identifies narrow shelf aisles by local width and neighbouring shelves, which is meaningful in any store layout."
  },
  {
    "id": "do_not_enter_single_file_aisle_with_cart",
    "text": "A shopper must not move from another area into a single-file shelf aisle while holding a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "or": [
            {
              "and": [
                "adjShelf",
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "adjShelf",
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileShelfAisleWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileShelfAisleWithCart"
    },
    "justification": "The event is defined by transitioning into a locally narrow shelf aisle, not by naming the aisle or its coordinates."
  },
  {
    "id": "park_cart_only_in_open_passing_space",
    "text": "If a shopper sets down a cart, they should do so only in an open passing space rather than in a shelf-front bottleneck.",
    "abstraction": {
      "state_properties": {
        "openPassingSpace": {
          "and": [
            {
              "not": "adjShelf"
            },
            {
              "ge": [
                "freeWidthH",
                3
              ]
            },
            {
              "ge": [
                "freeWidthV",
                3
              ]
            }
          ]
        }
      },
      "events": {
        "cartParked": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartParked",
          {
            "not": "openPassingSpace"
          }
        ]
      }
    },
    "justification": "The rule uses local openness and shelf adjacency to identify appropriate cart-parking places without referring to a specific cell."
  },
  {
    "id": "park_cart_only_for_single_file_errand",
    "text": "After parking a cart, the shopper should use the opportunity to enter a single-file shelf aisle on foot.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "or": [
            {
              "and": [
                "adjShelf",
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "adjShelf",
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {
        "cartParked": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "enterSingleFileShelfAisleOnFoot": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartParked",
      "discharge": "enterSingleFileShelfAisleOnFoot"
    },
    "justification": "The purpose of parking is tied to a generic accessibility constraint of narrow aisles, not to a named aisle in this particular map."
  },
  {
    "id": "retrieve_parked_cart",
    "text": "Whenever a shopper parks a cart, they should retrieve a cart again before the trip ends.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "cartParked": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "cartRetrieved": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartParked",
      "discharge": "cartRetrieved"
    },
    "justification": "The rule depends only on the cart-possession transition and therefore transfers across layouts with different parking locations."
  },
  {
    "id": "use_cart_at_cart_accessible_shelf_front",
    "text": "When interacting with a shelf from a cart-accessible shelf front, the shopper should keep the cart with them.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "or": [
            {
              "and": [
                "adjShelf",
                "shelfE",
                "shelfW",
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                }
              ]
            },
            {
              "and": [
                "adjShelf",
                "shelfN",
                "shelfS",
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                }
              ]
            }
          ]
        },
        "cartAccessibleShelfFront": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            },
            {
              "or": [
                {
                  "ge": [
                    "freeWidthH",
                    2
                  ]
                },
                {
                  "ge": [
                    "freeWidthV",
                    2
                  ]
                }
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartAccessibleShelfFront",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    },
    "justification": "Cart accessibility is defined from local aisle geometry and shelf adjacency, so the same rule distinguishes wide shelf fronts from narrow aisles in other stores."
  }
]
